import{c as n,Q as s,j as a,m as l}from"./chunks/framework.DOi4mjdC.js";const e="/assets/%E7%AE%97%E5%AD%90%E5%BC%80%E5%8F%91%E6%B5%81%E7%A8%8B.CDlCxmVL.png",i="/assets/%E6%95%B0%E6%8D%AE%E5%88%87%E5%88%86%E7%A4%BA%E6%84%8F%E5%9B%BE.CQ_-UB_H.png",p="/assets/%E5%A4%9A%E6%A0%B8%E5%B9%B6%E8%A1%8C%E5%A4%84%E7%90%86%E7%A4%BA%E6%84%8F%E5%9B%BE-38.Bv4uP4QJ.png",o="/assets/%E5%8D%95%E6%A0%B8%E6%95%B0%E6%8D%AE%E5%88%87%E5%88%86%E7%A4%BA%E6%84%8F%E5%9B%BE-39.CmyhvfPO.png",q=JSON.parse('{"title":"多核Tiling","description":"","frontmatter":{},"headers":[{"level":1,"title":"多核Tiling","slug":"多核tiling"},{"level":2,"title":"算子分析","slug":"算子分析"},{"level":2,"title":"Tiling实现","slug":"tiling实现"},{"level":2,"title":"算子类实现","slug":"算子类实现"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矢量编程/多核-Tiling切分/多核Tiling.md","filePath":"guide/算子实践参考/SIMD算子实现/矢量编程/多核-Tiling切分/多核Tiling.md"}'),g={name:"guide/算子实践参考/SIMD算子实现/矢量编程/多核-Tiling切分/多核Tiling.md"};function c(u,t,r,d,h,b){return s(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="多核tiling" tabindex="-1">多核Tiling <a class="header-anchor" href="#多核tiling" aria-label="Permalink to &quot;多核Tiling&quot;">​</a></h1><p>基于Ascend C方式实现带有Tiling的算子的开发流程如下图所示。</p><p><strong>图 1</strong> 算子开发流程<br><img src="'+e+'" alt="" title="算子开发流程"></p><h2 id="算子分析" tabindex="-1">算子分析 <a class="header-anchor" href="#算子分析" aria-label="Permalink to &quot;算子分析&quot;">​</a></h2><p>本样例为输入数据在核间均分、核内均分场景。本样例的Tiling策略为：数据整体长度TOTAL_LENGTH为8 * 2048，数据平均分配到8个核上运行，每个核上计算的数据长度BLOCK_LENGTH为2048，将单核上的数据切分成16块（此处切分成16块仅用来作为Tiling的样例，并不代表性能最佳，仅供参考），每块数据的长度TILE_LENGTH为128。数据切分示意如下图所示：</p><p><strong>图 2</strong> 数据切分示意图<br><img src="'+i+`" alt="" title="数据切分示意图"></p><p>通过以上分析，得到Ascend C Add算子的设计规格如下：</p><ul><li><p>算子类型（OpType）：Add</p></li><li><p>算子输入输出：</p><p><strong>表 1</strong> Add算子输入输出规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;name&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;shape&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;data type&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;format&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;x（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(8, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;y（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(8, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;z（输出）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(8, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;half&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>核函数名称：tiling_strategy_custom</p></li><li><p>使用的主要接口：</p><ul><li>DataCopy：数据搬移接口</li><li>Add：矢量基础算术接口</li><li>EnQue、DeQue等接口：Queue队列管理接口</li></ul></li><li><p>算子实现文件名称：tiling_strategy.asc</p></li></ul><h2 id="tiling实现" tabindex="-1">Tiling实现 <a class="header-anchor" href="#tiling实现" aria-label="Permalink to &quot;Tiling实现&quot;">​</a></h2><p>前述场景中算子的输入和输出均为固定shape，然而在实际的算子开发场景中，这些信息是支持动态变化的，场景会更加灵活和复杂。动态shape场景下，输入的shape是未知的。一些与输入shape相关的变量（比如每次搬运的块大小等），需要通过Tiling计算出来，然后传递到kernel侧，kernel侧使用该参数进行后续的计算。</p><p>具体实现方式为：分析设计Tiling参数、定义Tiling结构体，在Host侧通过上下文获取输入输出的shape信息，根据shape信息，计算Tiling参数并设置到对应的Tiling结构体中；通过核函数入口参数将Tiling信息传入核函数，在核函数内通过解析Tiling结构体，获取并使用相关参数来实现核函数内部逻辑，详细介绍请参考<a href="./../../../../编程指南/附录/工程化算子开发/Host侧Tiling实现/基本流程.html">Host侧tiling实现</a>。本节将以上述分析中的切分策略为例，说明如何实现Tiling。</p><p>基于本节的切分策略，Tiling需要定义如下参数：</p><ul><li>blockLength：每个核的计算数据长度；</li><li>tileNum：每个核需要计算的数据块个数；</li><li>tileLength：每个核内每个数据块的长度。</li></ul><p>根据确定的Tiling参数，使用C++语法定义TilingData结构体，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct AddCustomTilingData {</span></span>
<span class="line"><span>    uint32_t blockLength;</span></span>
<span class="line"><span>    uint32_t tileNum;</span></span>
<span class="line"><span>    uint32_t tileLength;</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>接下来完成Tiling参数的计算。由于每个核内数据被切分为16块，根据使用的核数和核内切分数，计算Tiling参数，并写入到Tiling结构体内。代码示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr int32_t NUM_BLOCKS = 8;                             // 使用的核数</span></span>
<span class="line"><span>constexpr int32_t TILE_NUM = 16;                             // 核内切分数量</span></span>
<span class="line"><span>void GenerateTilingData(uint8_t* tilingBuf, uint32_t numBlocks)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint32_t totalLength;</span></span>
<span class="line"><span>    // 此处省略如何获取数据总长TOTAL_LENGTH，可以根据具体情况实现。本章节仅介绍Tiling相关内容。</span></span>
<span class="line"><span>    AddCustomTilingData* tiling = reinterpret_cast&lt;AddCustomTilingData *&gt;(tilingBuf);</span></span>
<span class="line"><span>    uint32_t blockLength = TOTAL_LENGTH / numBlocks;</span></span>
<span class="line"><span>    uint32_t tileNum = TILE_NUM;</span></span>
<span class="line"><span>    uint32_t tileLength = blockLength / tileNum;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    tiling-&gt;blockLength = blockLength;</span></span>
<span class="line"><span>    tiling-&gt;tileNum = tileNum;</span></span>
<span class="line"><span>    tiling-&gt;tileLength = tileLength;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>最后，在Host侧调用程序中，调用上述Tiling参数计算函数，计算出相关参数，然后传递到Kernel侧核函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    constexpr int32_t NUM_BLOCKS = 8;</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    uint8_t *tiling = nullptr;</span></span>
<span class="line"><span>    size_t tilingSize = sizeof(AddCustomTilingData);</span></span>
<span class="line"><span>    GenerateTilingData(tiling, NUM_BLOCKS);  // 调用tiling参数计算函数</span></span>
<span class="line"><span>    ....</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    tiling_strategy_custom&lt;&lt;&lt;NUM_BLOCKS, nullptr, stream&gt;&gt;&gt;(xDevice, yDevice, zDevice,</span></span>
<span class="line"><span>                                               *reinterpret_cast&lt;AddCustomTilingData*&gt;(tiling));</span></span>
<span class="line"><span>    ....</span></span></code></pre></div><h2 id="算子类实现" tabindex="-1">算子类实现 <a class="header-anchor" href="#算子类实现" aria-label="Permalink to &quot;算子类实现&quot;">​</a></h2><p>Kernel侧算子实现仍遵循<a href="./../基础矢量算子.html#zh-cn_topic_0000002201157438_fig16061570280">矢量算子核函数实现流程</a>，接下来重点介绍本场景中算子类实现的不同点。</p><ul><li><p>设置输入输出Global Tensor的Global Memory内存地址。</p><p>由于本样例中将数据分配到了多个核上进行处理，每个核处理不同的数据，因此不同核要处理的数据在Global Memory上的地址不同，在初始化函数Init中，需要获取单核所需处理的输入输出在Global Memory上的内存偏移地址，并将该偏移地址设置到GlobalTensor中。</p><p>以获取输入x在Global Memory上的内存偏移地址为例，数据整体长度TOTAL_LENGTH为8 * 2048，平均分配到8个核上运行，每个核上处理的数据长度blockLength为2048，调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetBlockIdx.md" target="_blank" rel="noreferrer">GetBlockIdx</a>接口获取当前核的index，x + blockLength * GetBlockIdx()即为单核处理程序中x在Global Memory上的内存偏移地址，获取偏移地址后，使用GlobalTensor类的<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetGlobalBuffer.md" target="_blank" rel="noreferrer">SetGlobalBuffer</a>接口设定该核上Global Memory的起始地址以及长度，具体示意图请参考<a href="#zh-cn_topic_0000002236197677_fig398721711313">图3</a>。代码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xGm.SetGlobalBuffer((__gm__ half *)x + this-&gt;blockLength * AscendC::GetBlockIdx(), this-&gt;blockLength);</span></span></code></pre></div><p><strong>图 3</strong> 多核并行处理示意图<br><img src="`+p+'" alt="" title="多核并行处理示意图-38"></p></li><li><p>通过Pipe内存管理对象为输入输出Queue分配内存。</p><p>对于单核上的处理数据，可以进行数据切块（Tiling），在本示例中，仅作为参考，将单核上的数据（2048个数）切分成16块（并不意味着16块就是性能最优），每块tileLength（128）个数据。数据切分示意图如<a href="#zh-cn_topic_0000002236197677_fig1319211154719">图4</a>所示。</p><p><strong>图 4</strong> 单核数据切分示意图<br><img src="'+o+`" alt="" title="单核数据切分示意图-39"></p><p>与<a href="./../基础矢量算子.html">基础矢量算子</a>相比，在通过Pipe内存管理对象为输入输出Queue分配内存时，需使用单核内每个数据块的长度tileLength作为分配内存的长度。比如，为输入x的Queue分配内存，可以通过如下代码段实现，Pipe为inQueueX分配了一块大小为tileLength * sizeof(half)个字节的内存块，每个内存块能容纳tileLength（128）个half类型数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pipe-&gt;InitBuffer(inQueueX, 1, this-&gt;tileLength * sizeof(half))</span></span></code></pre></div></li></ul><p>具体的初始化函数代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, AddCustomTilingData tiling, AscendC::TPipe* pipeIn)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    pipe = pipeIn;</span></span>
<span class="line"><span>    this-&gt;blockLength = tiling.blockLength;</span></span>
<span class="line"><span>    this-&gt;tileNum = tiling.tileNum;</span></span>
<span class="line"><span>    this-&gt;tileLength = tiling.tileLength;</span></span>
<span class="line"><span>    // 计算每个核上的地址偏移</span></span>
<span class="line"><span>    xGm.SetGlobalBuffer((__gm__ half *)x + this-&gt;blockLength * AscendC::GetBlockIdx(), this-&gt;blockLength);</span></span>
<span class="line"><span>    yGm.SetGlobalBuffer((__gm__ half *)y + this-&gt;blockLength * AscendC::GetBlockIdx(), this-&gt;blockLength);</span></span>
<span class="line"><span>    zGm.SetGlobalBuffer((__gm__ half *)z + this-&gt;blockLength * AscendC::GetBlockIdx(), this-&gt;blockLength);</span></span>
<span class="line"><span>    // pipe alloc memory to queue, the unit is Bytes</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(inQueueX, 1, this-&gt;tileLength * sizeof(half));</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(inQueueY, 1, this-&gt;tileLength * sizeof(half));</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(outQueueZ, 1, this-&gt;tileLength * sizeof(half));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>每个核需要对tileNum个数据块分别进行搬入、计算、搬出处理，因此Process函数内将tileNum作为循环上限。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Process()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int32_t loopCount = this-&gt;tileNum;</span></span>
<span class="line"><span>    // tiling strategy, pipeline parallel</span></span>
<span class="line"><span>    for (int32_t i = 0; i &lt; loopCount; i++) {</span></span>
<span class="line"><span>        CopyIn(i, this-&gt;tileLength);</span></span>
<span class="line"><span>        Compute(i, this-&gt;tileLength);</span></span>
<span class="line"><span>        CopyOut(i, this-&gt;tileLength);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>对应的，每个核内搬入、搬出每个数据块时，需定位到每个数据块所在Global Memory上的内存偏移地址，因此在CopyIn和CopyOut函数内部使用DataCopy接口时，需增加每个数据块的地址偏移。Compute函数没有变化，与<a href="./../基础矢量算子.html">基础矢量算子</a>相同。</p><p>CopyIn函数实现代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void CopyIn(int32_t progress, uint32_t tileLength)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    // copy progress_th tile from global tensor to local tensor</span></span>
<span class="line"><span>    AscendC::DataCopy(xLocal, xGm[progress * this-&gt;tileLength], tileLength);</span></span>
<span class="line"><span>    AscendC::DataCopy(yLocal, yGm[progress * this-&gt;tileLength], tileLength);</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>CopyOut函数实现代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> __aicore__ inline void CopyOut(int32_t progress, uint32_t tileLength)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    // copy progress_th tile from local tensor to global tensor</span></span>
<span class="line"><span>    AscendC::DataCopy(zGm[progress * this-&gt;tileLength], zLocal, tileLength);</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,31)])])}const m=n(g,[["render",c]]);export{q as __pageData,m as default};
